const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// Basis-Schema für jede Tenant-Datenbank. Die DB-Grenze IST die Org-Grenze\n// (siehe CAPABILITY-MAP.md), daher kein organization_id-Spaltenmuster.\n// Wird von den folgenden Modulen erweitert: identity-org, projects-tasks, ...\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/tenant-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  owner\n  admin\n  member\n  client\n}\n\nenum Locale {\n  de\n  en\n}\n\nmodel User {\n  id                       String                   @id @default(uuid())\n  email                    String                   @unique\n  passwordHash             String? // null, solange die Einladung noch nicht angenommen wurde\n  name                     String?\n  role                     Role                     @default(member)\n  weeklyCapacityHours      Float                    @default(40)\n  isActive                 Boolean                  @default(true)\n  avatarUrl                String?\n  avatarStoragePath        String?\n  avatarMimeType           String?\n  internalCostRate         Float?\n  totpSecret               String?\n  totpEnabled              Boolean                  @default(false)\n  locale                   Locale                   @default(de)\n  createdAt                DateTime                 @default(now())\n  sessions                 Session[]\n  assignedTasks            Task[]\n  timeEntries              TimeEntry[]\n  comments                 Comment[]\n  mentions                 Mention[]\n  attachments              Attachment[]\n  activityEvents           ActivityEvent[]\n  notificationPreferences  NotificationPreference[]\n  notifications            Notification[]\n  dashboards               Dashboard[]\n  checkInResponses         CheckInResponse[]\n  ownedBudgets             Budget[]                 @relation(\"BudgetOwner\")\n  budgetSectionAssignments BudgetSectionAssignee[]  @relation(\"BudgetSectionAssignee\")\n  absenceRequests          AbsenceRequest[]         @relation(\"AbsenceRequester\")\n  reviewedAbsenceRequests  AbsenceRequest[]         @relation(\"AbsenceReviewer\")\n  createdAutomationRules   AutomationRule[]\n  automationActionTargets  AutomationAction[]\n  createdInvoices          Invoice[]\n  projectClientAccess      ProjectClientAccess[]\n  createdSharedViews       SharedView[]\n  createdTaskLinks         TaskLink[]\n  pendingLogins            PendingLogin[]\n  apiKeys                  ApiKey[]\n  customRole               CustomRole?              @relation(fields: [customRoleId], references: [id])\n  customRoleId             String?\n  projectRoleOverrides     ProjectRoleOverride[]\n  managedProjects          Project[]                @relation(\"ProjectManager\")\n  projectMemberships       ProjectMember[]\n  taskSubscriptions        TaskSubscriber[]\n  assignedTodos            Todo[]\n  savedViews               SavedView[]\n  sharedWikiLinks          SharedWikiLink[]\n  manager                  User?                    @relation(\"ManagerOf\", fields: [managerId], references: [id])\n  managerId                String?\n  directReports            User[]                   @relation(\"ManagerOf\")\n  favorites                Favorite[]\n  auditLogEntries          AuditLogEntry[]\n  invoicePayments          InvoicePayment[]\n  creditNotes              CreditNote[]\n  savedReports             SavedReport[]\n  approvedTimeEntries      TimeEntry[]              @relation(\"TimeEntryApprover\")\n  loggedForTimeEntries     TimeEntry[]              @relation(\"TimeEntryLoggedFor\")\n  timesheetLocks           TimesheetLock[]\n  lockedTimesheets         TimesheetLock[]          @relation(\"TimesheetLockedBy\")\n  holidayCalendar          HolidayCalendar?         @relation(fields: [holidayCalendarId], references: [id])\n  holidayCalendarId        String?\n  resourceBookings         ResourceBooking[]\n  createdResourceBookings  ResourceBooking[]        @relation(\"ResourceBookingCreator\")\n  createdMeetings          Meeting[]\n  createdExpenses          Expense[]\n  createdPurchaseOrders    PurchaseOrder[]\n  approvedExpenses         Expense[]                @relation(\"ExpenseApprover\")\n  createdWikiPages         WikiPage[]\n  accountOwnedClients      Client[]                 @relation(\"ClientAccountOwner\")\n  ownedDeals               Deal[]\n}\n\nenum ClientType {\n  customer\n  supplier\n  partner\n  internal\n  recruitment\n}\n\nmodel Client {\n  id               String          @id @default(uuid())\n  name             String\n  note             String?\n  taxId            String?\n  website          String?\n  billingAddress   String?\n  type             ClientType?\n  accountOwner     User?           @relation(\"ClientAccountOwner\", fields: [accountOwnerId], references: [id])\n  accountOwnerId   String?\n  paymentTermsDays Int?\n  archivedAt       DateTime?\n  parent           Client?         @relation(\"ClientHierarchy\", fields: [parentId], references: [id])\n  parentId         String?\n  children         Client[]        @relation(\"ClientHierarchy\")\n  createdAt        DateTime        @default(now())\n  projects         Project[]\n  contacts         ClientContact[]\n  deals            Deal[]\n  rateCards        RateCard[]\n\n  @@unique([name])\n}\n\nmodel ClientContact {\n  id        String   @id @default(uuid())\n  title     String?\n  client    Client   @relation(fields: [clientId], references: [id])\n  clientId  String\n  name      String\n  email     String?\n  phone     String?\n  isPrimary Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nenum DealStatusCategory {\n  open\n  won\n  lost\n}\n\n// Reference \"Setting up Your Sales Pipelines\": a Pipeline is an organization-wide,\n// reusable set of deal stages (several sales processes can have their own pipeline),\n// mirroring how Workflow does the same for task statuses. Archiving frees up the\n// plan's pipeline slot without deleting a Pipeline still referenced by a deal.\nmodel Pipeline {\n  id        String       @id @default(uuid())\n  name      String\n  archived  Boolean      @default(false)\n  createdAt DateTime     @default(now())\n  statuses  DealStatus[]\n}\n\nmodel DealStatus {\n  id                 String             @id @default(uuid())\n  pipeline           Pipeline           @relation(fields: [pipelineId], references: [id])\n  pipelineId         String\n  name               String\n  category           DealStatusCategory\n  position           Int\n  defaultProbability Int?\n  trackTime          Boolean            @default(true)\n  trackExpenses      Boolean            @default(true)\n  createBookings     Boolean            @default(true)\n  deals              Deal[]\n\n  @@unique([pipelineId, name])\n}\n\n// Reference \"General Sales Settings: Pipeline Stages, Lost Reasons...\": a managed\n// catalog instead of free text, so lost deals can actually be analyzed by reason.\nmodel LostReason {\n  id        String   @id @default(uuid())\n  label     String   @unique\n  archived  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  deals     Deal[]\n}\n\nmodel Deal {\n  id             String      @id @default(uuid())\n  title          String\n  company        Client      @relation(fields: [companyId], references: [id])\n  companyId      String\n  status         DealStatus  @relation(fields: [statusId], references: [id])\n  statusId       String\n  owner          User        @relation(fields: [ownerId], references: [id])\n  ownerId        String\n  estimatedValue Float?\n  probability    Int?\n  lostReason     LostReason? @relation(fields: [lostReasonId], references: [id])\n  lostReasonId   String?\n  lostReasonNote String?\n  project        Project?    @relation(fields: [projectId], references: [id])\n  projectId      String?\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n}\n\nmodel ProjectMember {\n  id        String   @id @default(uuid())\n  project   Project  @relation(fields: [projectId], references: [id])\n  projectId String\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  createdAt DateTime @default(now())\n\n  @@unique([projectId, userId])\n}\n\nmodel CustomRole {\n  id               String                @id @default(uuid())\n  name             String\n  permissions      String[]\n  createdAt        DateTime              @default(now())\n  users            User[]\n  projectOverrides ProjectRoleOverride[]\n\n  @@unique([name])\n}\n\nmodel ProjectRoleOverride {\n  id           String     @id @default(uuid())\n  project      Project    @relation(fields: [projectId], references: [id])\n  projectId    String\n  user         User       @relation(fields: [userId], references: [id])\n  userId       String\n  customRole   CustomRole @relation(fields: [customRoleId], references: [id])\n  customRoleId String\n  createdAt    DateTime   @default(now())\n\n  @@unique([projectId, userId])\n}\n\nenum AbsenceType {\n  vacation\n  sick\n}\n\nenum AbsenceStatus {\n  pending\n  approved\n  rejected\n}\n\nmodel AbsenceRequest {\n  id           String        @id @default(uuid())\n  user         User          @relation(\"AbsenceRequester\", fields: [userId], references: [id])\n  userId       String\n  type         AbsenceType\n  startDate    DateTime\n  endDate      DateTime\n  note         String?\n  status       AbsenceStatus @default(pending)\n  reviewedBy   User?         @relation(\"AbsenceReviewer\", fields: [reviewedById], references: [id])\n  reviewedById String?\n  reviewedAt   DateTime?\n  createdAt    DateTime      @default(now())\n}\n\nmodel Session {\n  id         String    @id @default(uuid())\n  userId     String\n  user       User      @relation(fields: [userId], references: [id])\n  expiresAt  DateTime\n  createdAt  DateTime  @default(now())\n  userAgent  String?\n  lastSeenAt DateTime?\n}\n\nmodel Favorite {\n  id         String   @id @default(uuid())\n  user       User     @relation(fields: [userId], references: [id])\n  userId     String\n  entityType String\n  entityId   String\n  createdAt  DateTime @default(now())\n\n  @@unique([userId, entityType, entityId])\n}\n\nmodel AuditLogEntry {\n  id         String   @id @default(uuid())\n  actor      User?    @relation(fields: [actorId], references: [id])\n  actorId    String?\n  action     String\n  entityType String\n  entityId   String?\n  summary    String\n  createdAt  DateTime @default(now())\n}\n\nmodel Invite {\n  id                String    @id @default(uuid())\n  email             String\n  token             String    @unique\n  role              Role      @default(member)\n  grantedProjectIds String[]  @default([])\n  expiresAt         DateTime\n  acceptedAt        DateTime?\n  createdAt         DateTime  @default(now())\n}\n\nmodel ProjectClientAccess {\n  project   Project @relation(fields: [projectId], references: [id])\n  projectId String\n  user      User    @relation(fields: [userId], references: [id])\n  userId    String\n\n  @@id([projectId, userId])\n}\n\nmodel SlackCaptureConfig {\n  id               String   @id @default(uuid())\n  signingSecret    String\n  defaultProject   Project  @relation(fields: [defaultProjectId], references: [id])\n  defaultProjectId String\n  enabled          Boolean  @default(false)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\nenum ProjectType {\n  client\n  internal\n}\n\nmodel Project {\n  id                      String                   @id @default(uuid())\n  name                    String\n  description             String?\n  budgetHours             Float?\n  budgetAmount            Float?\n  hourlyRate              Float?\n  type                    ProjectType              @default(internal)\n  color                   String                   @default(\"#5B8DEF\")\n  isTemplate              Boolean                  @default(false)\n  enabledModules          String[]                 @default([\"tasks\"])\n  timeApprovalRequired    Boolean                  @default(false)\n  expenseApprovalRequired Boolean                  @default(false)\n  createdAt               DateTime                 @default(now())\n  workflow                Workflow                 @relation(fields: [workflowId], references: [id])\n  workflowId              String\n  taskLinks               TaskProject[]\n  customFields            CustomFieldDef[]\n  timeEntries             TimeEntry[]\n  wikiPages               WikiPage[]\n  activityEvents          ActivityEvent[]\n  notificationPreferences NotificationPreference[]\n  checkInSchedules        CheckInSchedule[]\n  budgets                 Budget[]\n  transitionRules         TransitionRule[]\n  cycles                  Cycle[]\n  clientAccess            ProjectClientAccess[]\n  sharedViews             SharedView[]\n  slackCaptureConfigs     SlackCaptureConfig[]\n  portfolio               Portfolio?               @relation(fields: [portfolioId], references: [id])\n  portfolioId             String?\n  baselines               Baseline[]\n  roleOverrides           ProjectRoleOverride[]\n  client                  Client?                  @relation(fields: [clientId], references: [id])\n  clientId                String?\n  projectManager          User?                    @relation(\"ProjectManager\", fields: [projectManagerId], references: [id])\n  projectManagerId        String?\n  members                 ProjectMember[]\n  taskFolders             TaskFolder[]\n  savedViews              SavedView[]\n  resourceBookings        ResourceBooking[]\n  meetings                Meeting[]\n  expenses                Expense[]\n  purchaseOrders          PurchaseOrder[]\n  deals                   Deal[]\n  dashboardWidgetFilters  DashboardWidget[]\n  customFieldAttachments  ProjectCustomField[]\n}\n\nmodel TaskFolder {\n  id        String          @id @default(uuid())\n  project   Project         @relation(fields: [projectId], references: [id])\n  projectId String\n  name      String\n  position  Int             @default(0)\n  createdAt DateTime        @default(now())\n  lists     TaskListGroup[]\n}\n\nmodel TaskListGroup {\n  id        String     @id @default(uuid())\n  folder    TaskFolder @relation(fields: [folderId], references: [id])\n  folderId  String\n  name      String\n  position  Int        @default(0)\n  createdAt DateTime   @default(now())\n  tasks     Task[]\n}\n\nmodel Baseline {\n  id        String                 @id @default(uuid())\n  project   Project                @relation(fields: [projectId], references: [id])\n  projectId String\n  name      String\n  createdAt DateTime               @default(now())\n  snapshots BaselineTaskSnapshot[]\n}\n\nmodel BaselineTaskSnapshot {\n  id             String         @id @default(uuid())\n  baseline       Baseline       @relation(fields: [baselineId], references: [id])\n  baselineId     String\n  taskId         String\n  taskTitle      String\n  dueDate        DateTime?\n  estimatedHours Float?\n  statusCategory StatusCategory\n\n  @@unique([baselineId, taskId])\n}\n\nmodel Portfolio {\n  id          String    @id @default(uuid())\n  name        String\n  description String?\n  createdAt   DateTime  @default(now())\n  projects    Project[]\n  goals       Goal[]\n}\n\nenum GoalStatus {\n  on_track\n  at_risk\n  off_track\n  done\n}\n\nmodel Goal {\n  id          String     @id @default(uuid())\n  portfolio   Portfolio  @relation(fields: [portfolioId], references: [id])\n  portfolioId String\n  name        String\n  dueDate     DateTime?\n  status      GoalStatus @default(on_track)\n  createdAt   DateTime   @default(now())\n}\n\nmodel Cycle {\n  id        String   @id @default(uuid())\n  project   Project  @relation(fields: [projectId], references: [id])\n  projectId String\n  name      String\n  startDate DateTime\n  endDate   DateTime\n  createdAt DateTime @default(now())\n  tasks     Task[]\n}\n\nmodel TransitionRule {\n  id                String          @id @default(uuid())\n  project           Project         @relation(fields: [projectId], references: [id])\n  projectId         String\n  fromStatus        WorkflowStatus? @relation(\"TransitionFrom\", fields: [fromStatusId], references: [id])\n  fromStatusId      String?\n  toStatus          WorkflowStatus  @relation(\"TransitionTo\", fields: [toStatusId], references: [id])\n  toStatusId        String\n  requiredFieldKeys String[]\n  createdAt         DateTime        @default(now())\n}\n\nmodel SharedView {\n  id                   String          @id @default(uuid())\n  project              Project         @relation(fields: [projectId], references: [id])\n  projectId            String\n  token                String          @unique\n  statusCategoryFilter StatusCategory?\n  expiresAt            DateTime?\n  revokedAt            DateTime?\n  createdBy            User            @relation(fields: [createdById], references: [id])\n  createdById          String\n  createdAt            DateTime        @default(now())\n}\n\nmodel SavedView {\n  id            String   @id @default(uuid())\n  project       Project? @relation(fields: [projectId], references: [id])\n  projectId     String?\n  scope         String\n  name          String\n  viewType      String\n  filterConfig  Json\n  sortConfig    Json?\n  owner         User     @relation(fields: [ownerId], references: [id])\n  ownerId       String\n  sharedWithAll Boolean  @default(false)\n  createdAt     DateTime @default(now())\n}\n\nenum StatusCategory {\n  not_started\n  started\n  done\n}\n\n// Reference \"Creating and Managing Workflows\": a Workflow is an organization-wide,\n// reusable set of task statuses (grouped into not_started/started/done stages) —\n// several projects can point at the same Workflow, and editing it (e.g. moving a\n// status between stages) affects every project using it. Archiving frees up the\n// plan's workflow slot without deleting a Workflow still referenced by a project.\nmodel Workflow {\n  id        String           @id @default(uuid())\n  name      String\n  archived  Boolean          @default(false)\n  createdAt DateTime         @default(now())\n  statuses  WorkflowStatus[]\n  projects  Project[]\n}\n\nmodel WorkflowStatus {\n  id                String             @id @default(uuid())\n  workflow          Workflow           @relation(fields: [workflowId], references: [id])\n  workflowId        String\n  name              String\n  category          StatusCategory\n  position          Int\n  isDefault         Boolean            @default(false)\n  tasks             Task[]\n  transitionsFrom   TransitionRule[]   @relation(\"TransitionFrom\")\n  transitionsTo     TransitionRule[]   @relation(\"TransitionTo\")\n  automationActions AutomationAction[]\n\n  @@unique([workflowId, name])\n}\n\nenum TaskPriority {\n  no_priority\n  low\n  medium\n  high\n  urgent\n}\n\nenum TaskTShirtSize {\n  XS\n  S\n  M\n  L\n  XL\n}\n\nmodel Task {\n  id                  String             @id @default(uuid())\n  title               String\n  description         String?\n  externalSourceUrl   String?\n  status              WorkflowStatus     @relation(fields: [statusId], references: [id])\n  statusId            String\n  // Reference \"prioritize tasks inside a task list\" (drag reorder within a status\n  // column/list, persisted and shared between Board and List). Fractional so a drop\n  // between two neighbors only ever rewrites the moved task's row.\n  position            Float              @default(0)\n  priority            TaskPriority       @default(no_priority)\n  tShirtSize          TaskTShirtSize?\n  assignee            User?              @relation(fields: [assigneeId], references: [id])\n  assigneeId          String?\n  parentTask          Task?              @relation(\"Subtasks\", fields: [parentTaskId], references: [id])\n  parentTaskId        String?\n  subtasks            Task[]             @relation(\"Subtasks\")\n  startDate           DateTime?\n  dueDate             DateTime?\n  estimatedHours      Float?\n  hillPosition        Float?\n  inTriage            Boolean            @default(true)\n  isKeyTask           Boolean            @default(false)\n  isPrivate           Boolean            @default(false)\n  isTemplate          Boolean            @default(false)\n  taskListGroup       TaskListGroup?     @relation(fields: [taskListGroupId], references: [id])\n  taskListGroupId     String?\n  recurrence          Json?\n  recurrenceParent    Task?              @relation(\"RecurrenceInstances\", fields: [recurrenceParentId], references: [id])\n  recurrenceParentId  String?\n  recurrenceInstances Task[]             @relation(\"RecurrenceInstances\")\n  cycle               Cycle?             @relation(fields: [cycleId], references: [id])\n  cycleId             String?\n  cycleAssignedAt     DateTime?\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n  projects            TaskProject[]\n  blocking            TaskDependency[]   @relation(\"BlockingTask\")\n  blockedBy           TaskDependency[]   @relation(\"BlockedTask\")\n  linksAsSource       TaskLink[]         @relation(\"TaskLinkSource\")\n  linksAsTarget       TaskLink[]         @relation(\"TaskLinkTarget\")\n  customValues        CustomFieldValue[]\n  timeEntries         TimeEntry[]\n  comments            Comment[]\n  attachments         Attachment[]\n  tags                TaskTag[]\n  subscribers         TaskSubscriber[]\n  todos               Todo[]\n  activityEvents      ActivityEvent[]\n}\n\nmodel Tag {\n  id        String    @id @default(uuid())\n  name      String\n  createdAt DateTime  @default(now())\n  tasks     TaskTag[]\n\n  @@unique([name])\n}\n\nmodel TaskTag {\n  task   Task   @relation(fields: [taskId], references: [id])\n  taskId String\n  tag    Tag    @relation(fields: [tagId], references: [id])\n  tagId  String\n\n  @@id([taskId, tagId])\n}\n\nmodel TaskSubscriber {\n  id        String   @id @default(uuid())\n  task      Task     @relation(fields: [taskId], references: [id])\n  taskId    String\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  createdAt DateTime @default(now())\n\n  @@unique([taskId, userId])\n}\n\nmodel Todo {\n  id         String   @id @default(uuid())\n  task       Task     @relation(fields: [taskId], references: [id])\n  taskId     String\n  title      String\n  isDone     Boolean  @default(false)\n  assignee   User?    @relation(fields: [assigneeId], references: [id])\n  assigneeId String?\n  position   Int      @default(0)\n  createdAt  DateTime @default(now())\n}\n\nmodel Comment {\n  id        String    @id @default(uuid())\n  task      Task      @relation(fields: [taskId], references: [id])\n  taskId    String\n  author    User      @relation(fields: [authorId], references: [id])\n  authorId  String\n  body      String\n  createdAt DateTime  @default(now())\n  mentions  Mention[]\n}\n\nmodel Mention {\n  id        String  @id @default(uuid())\n  comment   Comment @relation(fields: [commentId], references: [id])\n  commentId String\n  user      User    @relation(fields: [userId], references: [id])\n  userId    String\n\n  @@unique([commentId, userId])\n}\n\nmodel Attachment {\n  id           String   @id @default(uuid())\n  task         Task     @relation(fields: [taskId], references: [id])\n  taskId       String\n  uploadedBy   User     @relation(fields: [uploadedById], references: [id])\n  uploadedById String\n  filename     String\n  mimeType     String\n  sizeBytes    Int\n  storagePath  String\n  createdAt    DateTime @default(now())\n}\n\nmodel WikiPage {\n  id           String                     @id @default(uuid())\n  project      Project                    @relation(fields: [projectId], references: [id])\n  projectId    String\n  title        String\n  content      String\n  isTemplate   Boolean                    @default(false)\n  createdBy    User?                      @relation(fields: [createdById], references: [id])\n  createdById  String?\n  createdAt    DateTime                   @default(now())\n  updatedAt    DateTime                   @updatedAt\n  customValues WikiPageCustomFieldValue[]\n  sharedLinks  SharedWikiLink[]\n}\n\nenum TimeTrackingMode {\n  timer\n  entries\n}\n\nmodel TenantSettings {\n  id                           String           @id @default(uuid())\n  allowProjectLevelTimeEntries Boolean          @default(false)\n  currency                     String           @default(\"EUR\")\n  triageEnabled                Boolean          @default(true)\n  timeTrackingMode             TimeTrackingMode @default(timer)\n  require2fa                   Boolean          @default(false)\n  scimBearerToken              String?\n  crmEnabled                   Boolean          @default(true)\n  reportsEnabled               Boolean          @default(true)\n  resourcingEnabled            Boolean          @default(true)\n  createdAt                    DateTime         @default(now())\n  updatedAt                    DateTime         @updatedAt\n}\n\nmodel PendingLogin {\n  id        String   @id @default(uuid())\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n}\n\nenum TimeEntryApprovalStatus {\n  pending\n  approved\n  rejected\n}\n\nmodel TimeEntry {\n  id              String                  @id @default(uuid())\n  user            User                    @relation(fields: [userId], references: [id])\n  userId          String\n  task            Task?                   @relation(fields: [taskId], references: [id])\n  taskId          String?\n  project         Project?                @relation(fields: [projectId], references: [id])\n  projectId       String?\n  budgetSection   BudgetSection?          @relation(fields: [budgetSectionId], references: [id])\n  budgetSectionId String?\n  amount          Float?\n  description     String?\n  startedAt       DateTime?\n  endedAt         DateTime?\n  durationMinutes Int?\n  createdAt       DateTime                @default(now())\n  invoice         Invoice?                @relation(fields: [invoiceId], references: [id])\n  invoiceId       String?\n  approvalStatus  TimeEntryApprovalStatus @default(pending)\n  approvedBy      User?                   @relation(\"TimeEntryApprover\", fields: [approvedById], references: [id])\n  approvedById    String?\n  approvedAt      DateTime?\n  loggedForUser   User?                   @relation(\"TimeEntryLoggedFor\", fields: [loggedForUserId], references: [id])\n  loggedForUserId String?\n}\n\nmodel TimesheetLock {\n  id          String   @id @default(uuid())\n  user        User     @relation(fields: [userId], references: [id])\n  userId      String\n  periodStart DateTime\n  periodEnd   DateTime\n  lockedBy    User     @relation(\"TimesheetLockedBy\", fields: [lockedById], references: [id])\n  lockedById  String\n  createdAt   DateTime @default(now())\n\n  @@unique([userId, periodStart, periodEnd])\n}\n\nmodel TimeTrackingPolicy {\n  id            String   @id @default(uuid())\n  maxDailyHours Float?\n  blockWeekends Boolean  @default(false)\n  blockOverlaps Boolean  @default(false)\n  updatedAt     DateTime @updatedAt\n}\n\nmodel HolidayCalendar {\n  id       String    @id @default(uuid())\n  name     String\n  country  String?\n  holidays Holiday[]\n  users    User[]\n\n  @@unique([name])\n}\n\nmodel Holiday {\n  id         String          @id @default(uuid())\n  calendar   HolidayCalendar @relation(fields: [calendarId], references: [id])\n  calendarId String\n  date       DateTime\n  name       String\n}\n\nmodel ResourceBooking {\n  id              String         @id @default(uuid())\n  user            User?          @relation(fields: [userId], references: [id])\n  userId          String?\n  placeholderName String?\n  project         Project        @relation(fields: [projectId], references: [id])\n  projectId       String\n  budgetSection   BudgetSection? @relation(fields: [budgetSectionId], references: [id])\n  budgetSectionId String?\n  startDate       DateTime\n  endDate         DateTime\n  hoursPerDay     Float\n  isTentative     Boolean        @default(false)\n  createdById     String\n  createdBy       User           @relation(\"ResourceBookingCreator\", fields: [createdById], references: [id])\n  createdAt       DateTime       @default(now())\n}\n\nmodel TaskProject {\n  task      Task    @relation(fields: [taskId], references: [id])\n  taskId    String\n  project   Project @relation(fields: [projectId], references: [id])\n  projectId String\n  isPrimary Boolean @default(true)\n\n  @@id([taskId, projectId])\n}\n\nmodel TaskDependency {\n  id             String @id @default(uuid())\n  blockingTask   Task   @relation(\"BlockingTask\", fields: [blockingTaskId], references: [id])\n  blockingTaskId String\n  blockedTask    Task   @relation(\"BlockedTask\", fields: [blockedTaskId], references: [id])\n  blockedTaskId  String\n\n  @@unique([blockingTaskId, blockedTaskId])\n}\n\nmodel TaskLink {\n  id           String   @id @default(uuid())\n  sourceTask   Task     @relation(\"TaskLinkSource\", fields: [sourceTaskId], references: [id])\n  sourceTaskId String\n  targetTask   Task     @relation(\"TaskLinkTarget\", fields: [targetTaskId], references: [id])\n  targetTaskId String\n  createdBy    User     @relation(fields: [createdById], references: [id])\n  createdById  String\n  createdAt    DateTime @default(now())\n\n  @@unique([sourceTaskId, targetTaskId])\n}\n\nenum CustomFieldType {\n  text\n  number\n  select\n  multi_select\n  date\n  person\n  url\n  percent\n}\n\nenum CustomFieldEntityType {\n  task\n  budget\n  wiki_page\n}\n\nmodel CustomFieldDef {\n  id                 String                     @id @default(uuid())\n  project            Project?                   @relation(fields: [projectId], references: [id])\n  projectId          String?\n  library            Boolean                    @default(false)\n  entityType         CustomFieldEntityType      @default(task)\n  key                String\n  label              String\n  type               CustomFieldType\n  options            String[]\n  taskValues         CustomFieldValue[]\n  budgetValues       BudgetCustomFieldValue[]\n  wikiPageValues     WikiPageCustomFieldValue[]\n  projectAttachments ProjectCustomField[]\n\n  @@unique([projectId, key])\n}\n\n// A library field is defined once (projectId null, library true) and shared\n// across many projects via this join table, instead of every project owning\n// its own private copy — mirrors the Workflow/Pipeline/RateCard \"centralize\n// as a shared, reusable entity\" pattern.\nmodel ProjectCustomField {\n  id        String         @id @default(uuid())\n  project   Project        @relation(fields: [projectId], references: [id])\n  projectId String\n  field     CustomFieldDef @relation(fields: [fieldId], references: [id])\n  fieldId   String\n  createdAt DateTime       @default(now())\n\n  @@unique([projectId, fieldId])\n}\n\nmodel CustomFieldValue {\n  id      String         @id @default(uuid())\n  field   CustomFieldDef @relation(fields: [fieldId], references: [id])\n  fieldId String\n  task    Task           @relation(fields: [taskId], references: [id])\n  taskId  String\n  value   String\n\n  @@unique([fieldId, taskId])\n}\n\nmodel BudgetCustomFieldValue {\n  id       String         @id @default(uuid())\n  field    CustomFieldDef @relation(fields: [fieldId], references: [id])\n  fieldId  String\n  budget   Budget         @relation(fields: [budgetId], references: [id])\n  budgetId String\n  value    String\n\n  @@unique([fieldId, budgetId])\n}\n\nmodel WikiPageCustomFieldValue {\n  id         String         @id @default(uuid())\n  field      CustomFieldDef @relation(fields: [fieldId], references: [id])\n  fieldId    String\n  wikiPage   WikiPage       @relation(fields: [wikiPageId], references: [id])\n  wikiPageId String\n  value      String\n\n  @@unique([fieldId, wikiPageId])\n}\n\nmodel SharedWikiLink {\n  id          String    @id @default(uuid())\n  wikiPage    WikiPage  @relation(fields: [wikiPageId], references: [id])\n  wikiPageId  String\n  token       String    @unique\n  revokedAt   DateTime?\n  createdBy   User      @relation(fields: [createdById], references: [id])\n  createdById String\n  createdAt   DateTime  @default(now())\n}\n\nenum ActivityEventType {\n  task_created\n  task_status_changed\n  task_updated\n  comment_added\n  attachment_added\n  wiki_page_created\n  wiki_page_updated\n  budget_created\n  budget_updated\n  budget_section_added\n  budget_section_updated\n  budget_section_removed\n  invoice_created\n}\n\nmodel ActivityEvent {\n  id            String            @id @default(uuid())\n  project       Project           @relation(fields: [projectId], references: [id])\n  projectId     String\n  actor         User              @relation(fields: [actorId], references: [id])\n  actorId       String\n  type          ActivityEventType\n  summary       String\n  task          Task?             @relation(fields: [taskId], references: [id])\n  taskId        String?\n  budget        Budget?           @relation(fields: [budgetId], references: [id])\n  budgetId      String?\n  createdAt     DateTime          @default(now())\n  notifications Notification[]\n}\n\nenum NotificationLevel {\n  all\n  mentions\n  off\n}\n\nmodel NotificationPreference {\n  id        String            @id @default(uuid())\n  user      User              @relation(fields: [userId], references: [id])\n  userId    String\n  project   Project           @relation(fields: [projectId], references: [id])\n  projectId String\n  level     NotificationLevel @default(all)\n\n  @@unique([userId, projectId])\n}\n\nmodel Notification {\n  id              String        @id @default(uuid())\n  user            User          @relation(fields: [userId], references: [id])\n  userId          String\n  activityEvent   ActivityEvent @relation(fields: [activityEventId], references: [id])\n  activityEventId String\n  readAt          DateTime?\n  createdAt       DateTime      @default(now())\n}\n\nenum AutomationTrigger {\n  task_created\n  task_status_changed\n  task_updated\n  task_commented\n  time_daily\n  time_weekly\n}\n\nenum AutomationActionType {\n  assign_user\n  notify_user\n  change_status\n  add_comment\n  create_task\n  create_subtask\n  create_todo\n  send_email\n}\n\nmodel AutomationRule {\n  id                      String              @id @default(uuid())\n  name                    String\n  triggers                AutomationTrigger[]\n  conditionStatusCategory StatusCategory?\n  projectIds              String[]            @default([])\n  scheduleTime            String?\n  scheduleWeekday         Int?\n  lastRunPeriodKey        String?\n  isEnabled               Boolean             @default(true)\n  createdBy               User                @relation(fields: [createdById], references: [id])\n  createdById             String\n  createdAt               DateTime            @default(now())\n  updatedAt               DateTime            @updatedAt\n  actions                 AutomationAction[]\n}\n\nmodel AutomationAction {\n  id             String               @id @default(uuid())\n  rule           AutomationRule       @relation(fields: [ruleId], references: [id])\n  ruleId         String\n  type           AutomationActionType\n  targetUser     User?                @relation(fields: [targetUserId], references: [id])\n  targetUserId   String?\n  targetStatus   WorkflowStatus?      @relation(fields: [targetStatusId], references: [id])\n  targetStatusId String?\n  commentBody    String?\n  newItemTitle   String?\n  position       Int                  @default(0)\n}\n\nmodel Dashboard {\n  id        String            @id @default(uuid())\n  name      String\n  owner     User              @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  ownerId   String\n  isDefault Boolean           @default(false)\n  position  Int               @default(0)\n  createdAt DateTime          @default(now())\n  widgets   DashboardWidget[]\n\n  @@unique([ownerId, name])\n}\n\nmodel DashboardWidget {\n  id              String    @id @default(uuid())\n  dashboard       Dashboard @relation(fields: [dashboardId], references: [id], onDelete: Cascade)\n  dashboardId     String\n  widgetType      String\n  title           String?\n  enabled         Boolean   @default(true)\n  position        Int\n  span            Int       @default(1)\n  filterProject   Project?  @relation(fields: [filterProjectId], references: [id], onDelete: SetNull)\n  filterProjectId String?\n  createdAt       DateTime  @default(now())\n}\n\nmodel WebhookEndpoint {\n  id                     String              @id @default(uuid())\n  url                    String\n  secret                 String\n  eventTypes             ActivityEventType[]\n  enabled                Boolean             @default(true)\n  integrationTemplateKey String?\n  createdAt              DateTime            @default(now())\n  deliveries             WebhookDelivery[]\n}\n\nmodel SsoConfig {\n  id         String   @id @default(uuid())\n  provider   String\n  entryPoint String\n  issuer     String\n  cert       String\n  enabled    Boolean  @default(false)\n  enforceSso Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\nenum ApiKeyScope {\n  read_only\n  read_write\n}\n\nmodel ApiKey {\n  id          String      @id @default(uuid())\n  name        String\n  tokenHash   String      @unique\n  tokenPrefix String\n  scope       ApiKeyScope @default(read_write)\n  user        User        @relation(fields: [userId], references: [id])\n  userId      String\n  lastUsedAt  DateTime?\n  revokedAt   DateTime?\n  createdAt   DateTime    @default(now())\n}\n\nmodel WebhookDelivery {\n  id              String          @id @default(uuid())\n  endpoint        WebhookEndpoint @relation(fields: [endpointId], references: [id])\n  endpointId      String\n  activityEventId String?\n  attempt         Int\n  statusCode      Int?\n  errorMessage    String?\n  success         Boolean\n  createdAt       DateTime        @default(now())\n}\n\nenum CheckInRecurrence {\n  daily\n  weekly\n}\n\nmodel CheckInSchedule {\n  id         String            @id @default(uuid())\n  project    Project           @relation(fields: [projectId], references: [id])\n  projectId  String\n  question   String\n  recurrence CheckInRecurrence\n  dayOfWeek  Int?\n  enabled    Boolean           @default(true)\n  createdAt  DateTime          @default(now())\n  responses  CheckInResponse[]\n}\n\nmodel CheckInResponse {\n  id         String          @id @default(uuid())\n  schedule   CheckInSchedule @relation(fields: [scheduleId], references: [id])\n  scheduleId String\n  user       User            @relation(fields: [userId], references: [id])\n  userId     String\n  periodKey  String\n  answer     String\n  createdAt  DateTime        @default(now())\n  updatedAt  DateTime        @updatedAt\n\n  @@unique([scheduleId, userId, periodKey])\n}\n\nenum RecurrenceInterval {\n  weekly\n  monthly\n}\n\nmodel Budget {\n  id                      String                   @id @default(uuid())\n  project                 Project                  @relation(fields: [projectId], references: [id])\n  projectId               String\n  title                   String\n  owner                   User                     @relation(\"BudgetOwner\", fields: [ownerId], references: [id])\n  ownerId                 String\n  isRetainer              Boolean                  @default(false)\n  recurrenceInterval      RecurrenceInterval?\n  lastRecurrencePeriodKey String?\n  startDate               DateTime?\n  endDate                 DateTime?\n  color                   String?\n  isScenario              Boolean                  @default(false)\n  scenarioOf              Budget?                  @relation(\"BudgetScenarios\", fields: [scenarioOfId], references: [id])\n  scenarioOfId            String?\n  scenarios               Budget[]                 @relation(\"BudgetScenarios\")\n  isTemplate              Boolean                  @default(false)\n  deliveredAt             DateTime?\n  createdAt               DateTime                 @default(now())\n  updatedAt               DateTime                 @updatedAt\n  sections                BudgetSection[]\n  invoices                Invoice[]\n  customFieldValues       BudgetCustomFieldValue[]\n  activityEvents          ActivityEvent[]\n  expenses                Expense[]\n}\n\nenum BillingType {\n  fixed\n  time_and_materials\n  non_billable\n  percentage\n}\n\nenum TrackingUnit {\n  hours\n  days\n  piece\n}\n\nmodel ServiceType {\n  id            String          @id @default(uuid())\n  name          String\n  createdAt     DateTime        @default(now())\n  sections      BudgetSection[]\n  rateCardItems RateCardItem[]\n  expenses      Expense[]\n\n  @@unique([name])\n}\n\nmodel BudgetSection {\n  id                      String                  @id @default(uuid())\n  budget                  Budget                  @relation(fields: [budgetId], references: [id])\n  budgetId                String\n  name                    String\n  description             String?\n  budgetedTimeHours       Float?\n  estimatedCost           Float?\n  quantity                Float\n  price                   Float\n  budgetUsed              Float                   @default(0)\n  serviceType             ServiceType?            @relation(fields: [serviceTypeId], references: [id])\n  serviceTypeId           String?\n  billingType             BillingType             @default(time_and_materials)\n  trackingUnit            TrackingUnit            @default(hours)\n  discountPercent         Float?\n  markupPercent           Float?\n  guaranteedMaxPrice      Float?\n  blockOverrun            Boolean                 @default(false)\n  trackTime               Boolean                 @default(true)\n  trackExpenses           Boolean                 @default(false)\n  trackBooking            Boolean                 @default(false)\n  warningThresholdPercent Float?\n  warningNotifiedAt       DateTime?\n  position                Int                     @default(0)\n  createdAt               DateTime                @default(now())\n  updatedAt               DateTime                @updatedAt\n  assignees               BudgetSectionAssignee[]\n  timeEntries             TimeEntry[]\n  lineItems               InvoiceLineItem[]\n  resourceBookings        ResourceBooking[]\n}\n\nmodel RateCard {\n  id        String         @id @default(uuid())\n  name      String\n  client    Client?        @relation(fields: [clientId], references: [id])\n  clientId  String?\n  archived  Boolean        @default(false)\n  createdAt DateTime       @default(now())\n  items     RateCardItem[]\n}\n\nmodel RateCardItem {\n  id            String       @id @default(uuid())\n  rateCard      RateCard     @relation(fields: [rateCardId], references: [id])\n  rateCardId    String\n  name          String\n  serviceType   ServiceType? @relation(fields: [serviceTypeId], references: [id])\n  serviceTypeId String?\n  billingType   BillingType  @default(time_and_materials)\n  trackingUnit  TrackingUnit @default(hours)\n  defaultPrice  Float\n  createdAt     DateTime     @default(now())\n}\n\nenum InvoiceStatus {\n  draft\n  finalized\n  sent\n  partially_paid\n  paid\n}\n\nenum InvoicingMethod {\n  uninvoiced_time_expenses\n  remaining_amount\n  percentage\n}\n\nmodel Invoice {\n  id              String            @id @default(uuid())\n  budget          Budget            @relation(fields: [budgetId], references: [id])\n  budgetId        String\n  status          InvoiceStatus     @default(draft)\n  invoicingMethod InvoicingMethod?\n  taxRatePercent  Float?\n  paidAmount      Float             @default(0)\n  finalizedAt     DateTime?\n  periodStart     DateTime\n  periodEnd       DateTime\n  totalAmount     Float\n  createdBy       User              @relation(fields: [createdById], references: [id])\n  createdById     String\n  createdAt       DateTime          @default(now())\n  lineItems       InvoiceLineItem[]\n  timeEntries     TimeEntry[]\n  payments        InvoicePayment[]\n  creditNotes     CreditNote[]\n}\n\nmodel InvoiceLineItem {\n  id              String        @id @default(uuid())\n  invoice         Invoice       @relation(fields: [invoiceId], references: [id])\n  invoiceId       String\n  budgetSection   BudgetSection @relation(fields: [budgetSectionId], references: [id])\n  budgetSectionId String\n  description     String\n  quantityHours   Float\n  rate            Float\n  amount          Float\n  taxRatePercent  Float?\n}\n\nmodel InvoicePayment {\n  id          String   @id @default(uuid())\n  invoice     Invoice  @relation(fields: [invoiceId], references: [id])\n  invoiceId   String\n  amount      Float\n  paidAt      DateTime\n  note        String?\n  createdBy   User     @relation(fields: [createdById], references: [id])\n  createdById String\n  createdAt   DateTime @default(now())\n}\n\nmodel CreditNote {\n  id          String   @id @default(uuid())\n  invoice     Invoice  @relation(fields: [invoiceId], references: [id])\n  invoiceId   String\n  amount      Float\n  reason      String?\n  createdBy   User     @relation(fields: [createdById], references: [id])\n  createdById String\n  createdAt   DateTime @default(now())\n}\n\nenum PurchaseOrderStatus {\n  draft\n  finalized\n  cancelled\n}\n\nenum PurchaseOrderSentStatus {\n  not_sent\n  sent\n}\n\nenum PurchaseOrderPaymentStatus {\n  not_received\n  partially_received\n  fully_received\n}\n\nenum ExpenseApprovalStatus {\n  pending\n  approved\n  rejected\n}\n\nmodel Meeting {\n  id          String   @id @default(uuid())\n  title       String\n  description String?\n  scheduledAt DateTime\n  project     Project? @relation(fields: [projectId], references: [id])\n  projectId   String?\n  createdBy   User     @relation(fields: [createdById], references: [id])\n  createdById String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Expense {\n  id             String                @id @default(uuid())\n  number         Int                   @default(autoincrement())\n  project        Project               @relation(fields: [projectId], references: [id])\n  projectId      String\n  budget         Budget?               @relation(fields: [budgetId], references: [id])\n  budgetId       String?\n  serviceType    ServiceType?          @relation(fields: [serviceTypeId], references: [id])\n  serviceTypeId  String?\n  description    String\n  amount         Float\n  billable       Boolean               @default(true)\n  incurredAt     DateTime\n  approvalStatus ExpenseApprovalStatus @default(pending)\n  approvedBy     User?                 @relation(\"ExpenseApprover\", fields: [approvedById], references: [id])\n  approvedById   String?\n  approvedAt     DateTime?\n  createdBy      User                  @relation(fields: [createdById], references: [id])\n  createdById    String\n  createdAt      DateTime              @default(now())\n  updatedAt      DateTime              @updatedAt\n}\n\nmodel PurchaseOrder {\n  id            String                     @id @default(uuid())\n  project       Project                    @relation(fields: [projectId], references: [id])\n  projectId     String\n  vendorName    String\n  amount        Float\n  status        PurchaseOrderStatus        @default(draft)\n  sentStatus    PurchaseOrderSentStatus    @default(not_sent)\n  paymentStatus PurchaseOrderPaymentStatus @default(not_received)\n  orderedAt     DateTime\n  createdBy     User                       @relation(fields: [createdById], references: [id])\n  createdById   String\n  createdAt     DateTime                   @default(now())\n  updatedAt     DateTime                   @updatedAt\n}\n\nmodel SavedReport {\n  id            String   @id @default(uuid())\n  name          String\n  category      String?\n  dataSource    String\n  filterConfig  Json\n  groupByConfig Json?\n  chartType     String?\n  owner         User     @relation(fields: [ownerId], references: [id])\n  ownerId       String\n  projectId     String?\n  createdAt     DateTime @default(now())\n}\n\nmodel BudgetSectionAssignee {\n  section   BudgetSection @relation(fields: [sectionId], references: [id])\n  sectionId String\n  user      User          @relation(\"BudgetSectionAssignee\", fields: [userId], references: [id])\n  userId    String\n\n  @@id([sectionId, userId])\n}\n"
}

